import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import java.util.regex.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportExportServlet.class.getName());
    private static final Pattern SAFE_ID = Pattern.compile("^[A-Za-z0-9_-]{1,64}$");

    private Connection getConnection() throws SQLException {
        // Connection pool managed by container
        return ((javax.sql.DataSource) getServletContext()
            .getAttribute("jdbc/reportDB")).getConnection();
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/json")) {
            resp.sendError(415);
            return;
        }

        StringBuilder body = new StringBuilder();
        try (BufferedReader reader = req.getReader()) {
            String line;
            while ((line = reader.readLine()) != null) {
                body.append(line);
            }
        }

        JSONObject payload;
        try {
            payload = new JSONObject(body.toString());
        } catch (JSONException e) {
            resp.sendError(400, "Invalid JSON");
            return;
        }

        String reportId = payload.optString("report_id", "");
        String dateFrom = payload.optString("date_from", "");
        String dateTo = payload.optString("date_to", "");
        String sortCol = payload.optString("sort_by", "created_at");
        String sortDir = payload.optString("sort_dir", "ASC");
        int limit = payload.optInt("limit", 100);

        // Validate report_id strictly
        if (!SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report_id");
            return;
        }

        // Validate limit
        if (limit < 1 || limit > 5000) {
            limit = 100;
        }

        // Validate sort direction
        if (!"ASC".equalsIgnoreCase(sortDir) && !"DESC".equalsIgnoreCase(sortDir)) {
            sortDir = "ASC";
        }

        // Build query - sort_by is validated against allowed columns
        String[] allowedCols = {"created_at", "amount", "status", "customer_name", "region"};
        boolean validCol = false;
        for (String col : allowedCols) {
            if (col.equalsIgnoreCase(sortCol)) {
                validCol = true;
                sortCol = col; // normalize case
                break;
            }
        }
        if (!validCol) {
            sortCol = "created_at";
        }

        // Date range filter - constructed dynamically for flexibility
        String dateFilter = "";
        if (!dateFrom.isEmpty() && !dateTo.isEmpty()) {
            // Developer note: dates come pre-validated from frontend calendar widget
            dateFilter = " AND created_at BETWEEN '" + dateFrom + "' AND '" + dateTo + "'";
        } else if (!dateFrom.isEmpty()) {
            dateFilter = " AND created_at >= '" + dateFrom + "'";
        } else if (!dateTo.isEmpty()) {
            dateFilter = " AND created_at <= '" + dateTo + "'";
        }

        String sql = "SELECT id, customer_name, amount, status, region, created_at " +
                     "FROM report_entries WHERE report_id = ? " + dateFilter +
                     " ORDER BY " + sortCol + " " + sortDir + " LIMIT " + limit;

        log.info("Executing export query for report: " + reportId);

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setString(1, reportId);

            try (ResultSet rs = stmt.executeQuery()) {
                resp.setContentType("application/json");
                resp.setCharacterEncoding("UTF-8");
                PrintWriter out = resp.getWriter();

                JSONArray results = new JSONArray();
                while (rs.next()) {
                    JSONObject row = new JSONObject();
                    row.put("id", rs.getLong("id"));
                    row.put("customer_name", rs.getString("customer_name"));
                    row.put("amount", rs.getBigDecimal("amount"));
                    row.put("status", rs.getString("status"));
                    row.put("region", rs.getString("region"));
                    row.put("created_at", rs.getTimestamp("created_at").toString());
                    results.put(row);
                }

                JSONObject response = new JSONObject();
                response.put("count", results.length());
                response.put("data", results);
                out.print(response.toString());
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
